import { writeFile } from "node:fs/promises";
import { createContext, runInContext } from "node:vm";
import { strict as assert } from "node:assert";
const imported = await import("../../../repo/tests/e2e/support/frontend-mission-evidence.ts");
const { waitForMissionRender } = imported.default ?? imported;

if (process.env.HF_UI044_F2_PROBE !== "1") throw new Error("EXPLICIT_SYNTHETIC_PROBE_REQUIRED");
const records = [];
for (const kind of ["idle", "finite-resolves", "finite-pending", "raf-pending", "message-pending"]) {
  const events = [];
  const log = event => events.push(event);
  let state = "running";
  let complete;
  const finished = new Promise(resolve => { complete = resolve; });
  const animation = {
    get playState() { return state; },
    effect: { getComputedTiming: () => ({ endTime: 300 }) },
    get finished() { log("animation.finished:await"); return finished; },
  };
  const context = createContext({
    __name: (fn, name) => Object.defineProperty(fn, "name", { value: name, configurable: true }),
    document: {
      getAnimations: () => {
        log("getAnimations");
        return kind.startsWith("finite-") && state === "running" ? [animation] : [];
      },
    },
    requestAnimationFrame: callback => {
      log("rAF:scheduled");
      if (kind !== "raf-pending") setImmediate(() => { log("rAF:executed"); callback(); });
    },
    MessageChannel: class {
      constructor() {
        const channel = this;
        this.port1 = { onmessage: null, close() {} };
        this.port2 = {
          postMessage() {
            log("message:posted");
            if (kind !== "message-pending") setImmediate(() => {
              log("message:delivered"); channel.port1.onmessage();
            });
          },
          close() {},
        };
      }
    },
  });
  if (kind === "finite-resolves") setImmediate(() => { state = "finished"; complete(); });
  const promise = runInContext(`(${waitForMissionRender.toString()})()`, context);
  let done = false;
  promise.then(() => { done = true; log("resolved"); });
  // Bounded diagnostic observation, not a changed test timeout or fallback.
  for (let turn = 0; turn < 8; turn++) await new Promise(resolve => setImmediate(resolve));
  assert.equal(done, kind === "idle" || kind === "finite-resolves");
  records.push({ kind, resolvedAfterEightNodeTurns: done, events });
}
const report = {
  status: "PASS_CONTROL_FLOW_ONLY",
  scope: "Exact imported official function evaluated with explicitly synthetic Node VM dependencies; no browser, product, DB, network or CI rerun.",
  limitation: "Demonstrates which await blocks when a primitive does not complete. Does not identify which primitive failed in F2, nor prove a browser bug or product fix.",
  records,
};
await writeFile(new URL("./probe-node-wait.json", import.meta.url), JSON.stringify(report, null, 2) + "\n");
console.log(JSON.stringify(report, null, 2));

import { strict as assert } from "node:assert";
import { createContext, runInContext } from "node:vm";
import { performance } from "node:perf_hooks";
import { writeFile } from "node:fs/promises";

if (process.env.HF_UI044_F2_PROBE !== "1") throw new Error("EXPLICIT_SYNTHETIC_PROBE_REQUIRED");
const officialModule = await import("../../../repo/tests/e2e/support/frontend-mission-evidence.ts");
const targetModule = await import("../../../wt-p03/tests/e2e/support/ui044-final-corrections.ts");
const { waitForMissionRender } = officialModule.default ?? officialModule;
const { installUI044RenderObservation } = targetModule.default ?? targetModule;
const cases = ["idle", "finite-resolves", "finite-rejects", "finite-pending", "raf-pending", "message-pending", "cancelled-frame", "invalid-frame", "callback-error", "callback-receiver", "message-constructor", "native-error", "console-error", "finite-inspection-error", "message-listener-error"];

async function exercise(kind, observed) {
  const trace = [];
  const observations = [];
  const ports = [];
  const cancelled = new Set();
  let frameId = 0;
  let playState = "running";
  let finish;
  let reject;
  let status = "PENDING";
  const finished = new Promise((resolve, fail) => { finish = resolve; reject = fail; });
  const animation = {
    get playState() { return playState; },
    get pending() { if (kind === "finite-inspection-error") throw new Error("DIAGNOSTIC_INSPECTION_SENTINEL"); return false; },
    currentTime: 0, timeline: { currentTime: 0 },
    effect: { target: { tagName: "BUTTON" }, getComputedTiming: () => ({ endTime: 300 }) },
    get finished() { return finished; },
  };
  let host;
  class Port {
    listeners = new Set();
    started = false;
    closed = false;
    handler = null;
    addEventListener(name, listener) { assert.equal(name, "message"); if (kind === "message-listener-error") throw new Error("DIAGNOSTIC_LISTENER_SENTINEL"); this.listeners.add(listener); }
    removeEventListener(name, listener) { assert.equal(name, "message"); this.listeners.delete(listener); }
    set onmessage(handler) { this.handler = handler; this.started = true; trace.push("port-start"); }
    get onmessage() { return this.handler; }
    close() { this.closed = true; trace.push("port-close"); }
    deliver() {
      if (!this.started || this.closed) return;
      trace.push("message-delivered");
      const event = { data: null, target: this };
      for (const listener of this.listeners) listener.call(this, event);
      this.handler?.call(this, event);
    }
  }
  class NativeMessageChannel {
    constructor() {
      trace.push("channel-created");
      this.port1 = new Port();
      this.port2 = new Port();
      this.port2.postMessage = () => {
        trace.push("message-posted");
        if (kind !== "message-pending") setImmediate(() => this.port1.deliver());
      };
      ports.push(this.port1, this.port2);
    }
  }
  const nativeAnimations = function () {
    trace.push("getAnimations");
    if (kind === "native-error") throw new Error("NATIVE_SENTINEL");
    return kind.startsWith("finite-") && playState === "running" ? [animation] : [];
  };
  host = {
    // tsx's emitted helper changes function names only; no async semantics.
    __name: (fn, name) => Object.defineProperty(fn, "name", { value: name, configurable: true }),
    console: { info: value => { if (kind === "console-error") throw new Error("DIAGNOSTIC_CONSOLE_SENTINEL"); observations.push(JSON.parse(value.replace(/^UI044_RENDER_OBSERVATION /, ""))); } },
    performance, innerWidth: 390, innerHeight: 844,
    document: Object.assign(Object.create({ getAnimations: nativeAnimations }), { visibilityState: "visible" }),
    requestAnimationFrame: function (callback) {
      if (typeof callback !== "function") throw new TypeError("NATIVE_INVALID_CALLBACK");
      const id = ++frameId;
      trace.push(`frame-scheduled:${id}`);
      if (kind !== "raf-pending") setImmediate(() => {
        if (cancelled.has(id)) return;
        trace.push(`frame-delivered:${id}`);
        try { callback.call(kind === "callback-receiver" ? host.receiver : host.window, 123.75); }
        catch (error) { trace.push(`callback-error:${error.message}`); }
      });
      return id;
    },
    cancelAnimationFrame: id => { cancelled.add(id); trace.push(`frame-cancelled:${id}`); },
    MessageChannel: NativeMessageChannel,
    receiver: {},
    recordCallback: (receiver, timestamp) => {
      trace.push(`callback-receiver:${receiver === host.receiver}:timestamp:${timestamp}`);
      assert.equal(receiver, host.receiver);
      assert.equal(timestamp, 123.75);
    },
  };
  const context = createContext(host);
  runInContext("window = globalThis", context);
  if (kind === "partial-install") {
    const frames = host.requestAnimationFrame;
    Object.defineProperty(host, "requestAnimationFrame", { configurable: true, enumerable: true, get: () => frames, set: () => { throw new Error("PARTIAL_INSTALL_SENTINEL"); } });
  }
  const descriptors = {
    animations: Object.getOwnPropertyDescriptor(host.document, "getAnimations"),
    frames: Object.getOwnPropertyDescriptor(host, "requestAnimationFrame"),
    channel: Object.getOwnPropertyDescriptor(host, "MessageChannel"),
  };
  const install = () => runInContext(`(${installUI044RenderObservation.toString()})({ head: "synthetic-no-product", diagnosis: false, actions: false, profile: "member" })`, context);
  if (kind === "partial-install") {
    assert.throws(install, /PARTIAL_INSTALL_SENTINEL/);
    assert.deepEqual(Object.getOwnPropertyDescriptor(host.document, "getAnimations"), descriptors.animations);
    assert.deepEqual(Object.getOwnPropertyDescriptor(host, "requestAnimationFrame"), descriptors.frames);
    assert.deepEqual(Object.getOwnPropertyDescriptor(host, "MessageChannel"), descriptors.channel);
    assert.equal(host.__ui044RestoreRenderObservation, undefined);
    return { status: "INSTALL_REJECTED_AND_ROLLED_BACK", descriptorsRestored: true, observations };
  }
  if (observed) install();
  assert.equal(host.MessageChannel.prototype, NativeMessageChannel.prototype);
  if (kind === "cancelled-frame") runInContext("cancelAnimationFrame(requestAnimationFrame(() => { throw Error('CANCELLED_CALLBACK_RAN'); }))", context);
  if (kind === "invalid-frame") assert.throws(() => host.requestAnimationFrame(null), /NATIVE_INVALID_CALLBACK/);
  if (kind === "callback-error") runInContext("requestAnimationFrame(() => { throw Error('CALLBACK_SENTINEL'); })", context);
  if (kind === "callback-receiver") runInContext("requestAnimationFrame(function (timestamp) { recordCallback(this, timestamp); })", context);
  if (kind === "message-constructor") {
    const channel = runInContext("(() => { class Child extends MessageChannel {} const channel = new Child(); if (Object.getPrototypeOf(channel) !== Child.prototype) throw Error('LOST_NEW_TARGET'); return channel; })()", context);
    assert.ok(channel instanceof NativeMessageChannel);
    assert.equal(channel.port1.started, false, "Observation does not start an idle port");
  }
  if (kind === "finite-resolves" || kind === "finite-inspection-error") setImmediate(() => { playState = "finished"; finish(); });
  if (kind === "finite-rejects") setImmediate(() => { playState = "idle"; reject(new Error("CANCELLED_SYNTHETIC_ANIMATION")); });
  const promise = runInContext(`(${waitForMissionRender.toString()})()`, context);
  promise.then(() => { status = "RESOLVED"; trace.push("wait-resolved"); }, error => { status = `REJECTED:${error.message}`; trace.push(status); });
  for (let turn = 0; turn < 8; turn++) await new Promise(resolve => setImmediate(resolve));
  if (observed) runInContext("__ui044RestoreRenderObservation()", context);
  assert.deepEqual(Object.getOwnPropertyDescriptor(host.document, "getAnimations"), descriptors.animations);
  assert.deepEqual(Object.getOwnPropertyDescriptor(host, "requestAnimationFrame"), descriptors.frames);
  assert.deepEqual(Object.getOwnPropertyDescriptor(host, "MessageChannel"), descriptors.channel);
  assert.equal(host.document.getAnimations, nativeAnimations);
  assert.equal(host.__ui044RestoreRenderObservation, undefined);
  for (const port of ports) assert.equal(port.listeners.size, 0);
  return { status, trace, observations, descriptorsRestored: true, listenersRemoved: true };
}

const results = [];
for (const kind of cases) {
  const plain = await exercise(kind, false);
  const observed = await exercise(kind, true);
  assert.equal(observed.status, plain.status, kind);
  assert.deepEqual(observed.trace, plain.trace, kind);
  const expected = kind.endsWith("-pending") ? "PENDING" : kind === "native-error" ? "REJECTED:NATIVE_SENTINEL" : "RESOLVED";
  assert.equal(observed.status, expected, kind);
  if (kind === "finite-pending") assert.equal(observed.observations.findLast(event => event.event === "animations-sampled").counters.finite, 1);
  if (kind === "raf-pending") assert.equal(observed.observations.findLast(event => event.event === "observer-restored").counters.frames, 0);
  if (kind === "message-pending") {
    const counters = observed.observations.findLast(event => event.event === "observer-restored").counters;
    assert.equal(counters.frames, 2);
    assert.equal(counters.channels, 1);
    assert.equal(counters.messages, 0);
  }
  results.push({ kind, equivalentNativeTrace: true, ...observed });
}
results.push({ kind: "partial-install", ...await exercise("partial-install", true) });
const report = {
  status: "PASS_SYNTHETIC_OBSERVER_EQUIVALENCE",
  assertions: "Same imported official wait, with and without the exact imported observer; same native trace, completion/rejection/pending state, RAF IDs/cancellation, native exceptions, descriptors and listener cleanup.",
  limitation: "Deterministic Node VM primitives. Does not prove browser implementation equivalence, F2 root cause, application runtime or CI succession. Pending cases are controlled fixtures, never claimed as F2 RED.",
  cases: results,
};
await writeFile(new URL("./probe-observer-equivalence.json", import.meta.url), JSON.stringify(report, null, 2) + "\n");
console.log(JSON.stringify({ status: report.status, cases: results.map(({ kind, status }) => ({ kind, status })) }, null, 2));
